// Jarvis marks from the brand artwork (generated by backend/scripts/make_brand_assets.py):
// - Emblem: the arc-reactor mark, legible at small sizes; spins while busy.
// - Logo: the full J.A.R.V.I.S. HUD ring for large placements.
import { cx } from './ui';

export function Emblem({ size = 28, spin = false, glow = 1 }: { size?: number; spin?: boolean; glow?: number }) {
  const g = Math.max(0.6, Math.min(1.4, glow));
  return (
    <img src="./brand/reactor.png" alt="" width={size} height={size} draggable={false}
      className={cx('rounded-full select-none', spin && 'animate-spin-slow')}
      style={{ filter: `drop-shadow(0 0 ${Math.round(size * 0.12 * g)}px rgba(79,209,245,${0.35 * g})) brightness(${0.9 + 0.15 * g})` }} />
  );
}

export function Logo({ size = 96, className }: { size?: number; className?: string }) {
  return (
    <img src="./brand/logo.png" alt="Jarvis" width={size} height={size} draggable={false}
      className={cx('rounded-full select-none drop-shadow-[0_0_24px_rgba(79,209,245,0.35)]', className)} />
  );
}
